using System;using System.Linq;public class Solution{public int MaximumGap(int[]a){int n=a.Length;if(n<2)return 0;int mn=a.Min(),mx=a.Max();if(mn==mx)return 0;int sz=(mx-mn+n-2)/(n-1),bc=(mx-mn)/sz+1;int[]lo=new int[bc],hi=new int[bc];bool[]u=new bool[bc];Array.Fill(lo,int.MaxValue);Array.Fill(hi,int.MinValue);foreach(int x in a){int k=(x-mn)/sz;u[k]=true;lo[k]=Math.Min(lo[k],x);hi[k]=Math.Max(hi[k],x);}int p=mn,b=0;for(int i=0;i<bc;i++)if(u[i]){b=Math.Max(b,lo[i]-p);p=hi[i];}return b;}}
